def bloco_key(numero):
    return numero[0] if numero else "?"


def find_json():
    base = os.path.dirname(os.path.abspath(__file__))
    for p in [
        os.path.join(base, "efd_registros_estrutura_regras.json"),
        os.path.join(base, "efd_registros.json"),
        os.path.join(base, "data", "efd_registros_estrutura_regras.json"),
        os.path.join(base, "data", "efd_registros.json"),
    ]:
        if os.path.exists(p):
            return p
    return ""


def clean_text(text):
    if not text:
        return ""
    lines = [ln.strip() for ln in text.split("\n")]
    result, prev_blank = [], False
    for ln in lines:
        if ln == "":
            if not prev_blank:
                result.append("")
            prev_blank = True
        else:
            result.append(ln)
            prev_blank = False
    return "\n".join(result).strip()


def format_bloco_value(bloco):
    if not bloco:
        return "—"
    bloco = str(bloco).strip()
    if bloco in BLOCOS:
        return BLOCOS[bloco]
    return bloco


def format_filhos_diretos(filhos):
    if not filhos:
        return ["• Nenhum"]
    return [f"• {filho}" for filho in filhos]


